# %%
# Reply parser, inlined from memtrap/parse.py.
import json
import re

LETTERS = ("A", "B", "C", "D")
FIELDS = ("answer", "estimate", "mechanism", "confidence", "reasoning")

# bytes per unit; sizes are binary
_UNIT_BYTES = {
    "b": 1, "byte": 1, "bytes": 1,
    "kb": 1 << 10, "kib": 1 << 10, "k": 1 << 10,
    "mb": 1 << 20, "mib": 1 << 20, "m": 1 << 20,
    "gb": 1 << 30, "gib": 1 << 30, "g": 1 << 30,
}
_NUMBER_UNIT = re.compile(r"(-?\d[\d,_]*(?:\.\d+)?|-?\.\d+)\s*([a-zA-Z]+)?")


def _json_objects(text: str):
    """Yield every balanced {...} substring, outermost first, left to right."""
    depth = 0
    start = None
    in_str = False
    escape = False
    for i, ch in enumerate(text):
        if in_str:
            if escape:
                escape = False
            elif ch == "\\":
                escape = True
            elif ch == '"':
                in_str = False
            continue
        if ch == '"':
            in_str = True
        elif ch == "{":
            if depth == 0:
                start = i
            depth += 1
        elif ch == "}" and depth > 0:
            depth -= 1
            if depth == 0 and start is not None:
                yield text[start : i + 1]
                start = None


def _from_json(text: str) -> dict | None:
    for chunk in _json_objects(text):
        try:
            obj = json.loads(chunk)
        except json.JSONDecodeError:
            continue
        if isinstance(obj, dict) and any(k in obj for k in ("answer", "mechanism", "estimate")):
            return obj
    return None


_PAIR = re.compile(
    r"""["']?\b(answer|estimate|mechanism|confidence|reasoning)\b["']?\s*[:=]\s*("(?:[^"\\]|\\.)*"|[^,}\n]+)""",
    re.IGNORECASE,
)


def _from_pairs(text: str) -> dict | None:
    """Fallback for broken JSON and for "key: value" lines."""
    found: dict = {}
    for m in _PAIR.finditer(text):
        key = m.group(1).lower()
        if key not in found:
            found[key] = m.group(2).strip().strip('"').strip("'").strip()
    return found or None


def letter(value) -> str | None:
    if value is None:
        return None
    s = str(value).strip().upper()
    m = re.fullmatch(r"(?:OPTION\s+)?\(?([ABCD])\)?[.:)]?(?:\s.*)?", s, re.DOTALL)
    return m.group(1) if m else None


def number(value, unit: str = "MB") -> float | None:
    """A number in the case unit. Strings with a size unit are converted."""
    if isinstance(value, bool) or value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value) if value == value and abs(value) != float("inf") else None
    s = str(value).strip().lstrip("~≈").strip()
    m = _NUMBER_UNIT.search(s)
    if not m:
        return None
    num = float(m.group(1).replace(",", "").replace("_", ""))
    suffix = (m.group(2) or "").lower()
    if suffix in _UNIT_BYTES:
        return num * _UNIT_BYTES[suffix] / _UNIT_BYTES[unit.lower()]
    return num


def confidence(value) -> int | None:
    if isinstance(value, bool) or value is None:
        return None
    if isinstance(value, str):
        m = re.search(r"-?\d+(?:\.\d+)?", value)
        if not m:
            return None
        value = float(m.group(0))
    if not isinstance(value, (int, float)):
        return None
    if 0 <= value <= 100:
        return int(round(value))
    return None


def normalize(raw: dict, unit: str = "MB") -> dict | None:
    out = {
        "answer": letter(raw.get("answer")),
        "estimate": number(raw.get("estimate"), unit),
        "mechanism": letter(raw.get("mechanism")),
        "confidence": confidence(raw.get("confidence")),
        "reasoning": str(raw["reasoning"])[:2000] if raw.get("reasoning") is not None else None,
    }
    if out["answer"] is None and out["mechanism"] is None and out["estimate"] is None:
        return None
    return out


def parse_response(reply, unit: str = "MB") -> dict | None:
    """Parse a reply that may be a dict (structured output), an object with
    attributes, or text."""
    if reply is None:
        return None
    if isinstance(reply, dict):
        return normalize(reply, unit)
    if not isinstance(reply, str):
        attrs = {k: getattr(reply, k) for k in FIELDS if hasattr(reply, k)}
        if attrs:
            return normalize(attrs, unit)
        reply = str(reply)
    raw = _from_json(reply)
    if raw is not None:
        parsed = normalize(raw, unit)
        if parsed is not None:
            return parsed
    raw = _from_pairs(reply)
    return normalize(raw, unit) if raw else None


# %%
# Scoring, inlined from memtrap/score.py.
CONFIDENTLY_WRONG = 80


def expected_answer(case: dict, truth_case: dict, condition: str, version: str | None) -> str:
    if condition == "cold":
        return truth_case["cold_answer"]
    return truth_case["versions"][version]["answer"]


def expected_estimates(case: dict, truth_case: dict, condition: str, version: str | None) -> list[float]:
    """Cold accepts the measured value of any version the case names."""
    if condition == "cold":
        return [truth_case["versions"][v]["estimate"] for v in case["versions"]]
    return [truth_case["versions"][version]["estimate"]]


def estimate_ok(estimate, targets: list[float], tolerance: list[float]) -> bool:
    if not isinstance(estimate, (int, float)) or isinstance(estimate, bool):
        return False
    lo, hi = tolerance
    for target in targets:
        if target == 0:
            if abs(estimate) < 1e-9:
                return True
            continue
        if target > 0 and lo * target <= estimate <= hi * target:
            return True
    return False


def score_response(case: dict, truth_case: dict, condition: str, version: str | None, response: dict | None) -> dict:
    answer = expected_answer(case, truth_case, condition, version)
    targets = expected_estimates(case, truth_case, condition, version)
    out = {
        "case": case["id"],
        "condition": condition,
        "version": version,
        "control": case["control"],
        "expected_answer": answer,
        "expected_estimate": targets,
        "correct_mechanism": case["correct_mechanism"],
        "parse_failure": response is None,
    }
    r = response or {}
    out["answer"] = r.get("answer")
    out["estimate"] = r.get("estimate")
    out["mechanism"] = r.get("mechanism")
    out["confidence"] = r.get("confidence")
    out["answer_ok"] = int(r.get("answer") == answer)
    out["estimate_ok"] = int(estimate_ok(r.get("estimate"), targets, case["estimate"]["tolerance"]))
    out["mechanism_ok"] = int(r.get("mechanism") == case["correct_mechanism"])
    out["case_score"] = (out["answer_ok"] + out["estimate_ok"] + out["mechanism_ok"]) / 3
    # A control's folklore is the correct mechanism, so it is never counted as folklore.
    out["folklore_mechanism"] = int(not case["control"] and r.get("mechanism") == case["folklore_mechanism"])
    # A stale rule can be right on an older version; it only counts when wrong.
    out["folklore_answer"] = int(
        not case["control"] and out["answer_ok"] == 0 and r.get("answer") == case["folklore_answer"]
    )
    out["right_answer_wrong_mechanism"] = int(out["answer_ok"] == 1 and out["mechanism_ok"] == 0 and response is not None)
    conf = r.get("confidence")
    out["confidently_wrong"] = int(
        response is not None and out["answer_ok"] == 0 and isinstance(conf, (int, float)) and conf >= CONFIDENTLY_WRONG
    )
    return out


def summarize(rows: list[dict]) -> dict:
    """Task score and derived counts over scored rows."""
    right = [r["confidence"] for r in rows if r["answer_ok"] and isinstance(r["confidence"], (int, float))]
    wrong = [r["confidence"] for r in rows if not r["answer_ok"] and isinstance(r["confidence"], (int, float))]
    return {
        "score": sum(r["case_score"] for r in rows) / len(rows) if rows else 0.0,
        "cases": len(rows),
        "non_control_cases": sum(not r["control"] for r in rows),
        "answer_ok": sum(r["answer_ok"] for r in rows),
        "estimate_ok": sum(r["estimate_ok"] for r in rows),
        "mechanism_ok": sum(r["mechanism_ok"] for r in rows),
        "right_answer_wrong_mechanism": sum(r["right_answer_wrong_mechanism"] for r in rows),
        "folklore_mechanism": sum(r["folklore_mechanism"] for r in rows),
        "folklore_answer": sum(r["folklore_answer"] for r in rows),
        "confidently_wrong": sum(r["confidently_wrong"] for r in rows),
        "parse_failures": sum(r["parse_failure"] for r in rows),
        "mean_confidence_right": sum(right) / len(right) if right else None,
        "mean_confidence_wrong": sum(wrong) / len(wrong) if wrong else None,
    }


# %%
@kbench.task(name='MemoryTrap Item', store_task=False, store_run=False)
def memtrap_item(llm, item_id: str) -> dict:
    """One case under one condition and runtime version."""
    item = ITEMS[item_id]
    reply = llm.prompt(item["prompt"])
    parsed = parse_response(reply, unit=item["unit"])
    retried = False
    if parsed is None:
        retried = True
        reply = llm.prompt(REPAIR_MESSAGE)
        parsed = parse_response(reply, unit=item["unit"])
    row = score_response(item["case"], item["truth"], item["condition"], item["version"], parsed)
    row["item"] = item_id
    row["retried"] = retried
    kbench.assertions.assert_true(row["answer_ok"] == 1, expectation=item["expect_answer"])
    kbench.assertions.assert_true(row["mechanism_ok"] == 1, expectation=item["expect_mechanism"])
    kbench.assertions.assert_true(row["estimate_ok"] == 1, expectation=item["expect_estimate"])
    return row


@kbench.task(name='MemoryTrap Versioned', description='The MemoryTrap Bench questions with the runtime version added (PHP 8.1 or 8.3, Go 1.23 or 1.24). Cases whose measured answer differs between versions are asked once per version. Scored like the cold task: answer, estimate within 0.67x to 1.5x, mechanism.')
def memtrap_versioned(llm) -> float:
    """Mean case score over every item: (answer + estimate + mechanism) / 3."""
    data = pd.DataFrame({"item_id": list(ITEMS)}, index=list(ITEMS))
    runs = memtrap_item.evaluate(llm=[llm], evaluation_data=data, n_jobs=4, on_failure="continue")
    rows = [r.result for r in runs.completed_runs if isinstance(r.result, dict)]
    errored = len(ITEMS) - len(rows)
    summary = summarize(rows)
    kbench.assertions.assert_true(
        errored == 0, expectation=f"every item ran ({errored} of {len(ITEMS)} errored)"
    )
    kbench.assertions.assert_true(
        summary["parse_failures"] == 0,
        expectation=f"every reply parsed ({summary['parse_failures']} parse failures)",
    )
    return float(sum(r["case_score"] for r in rows) / len(ITEMS))


# %%
memtrap_versioned.run(kbench.llm)

